582 :         DateFormatSymbols symbols = new DateFormatSymbols(mLocale);
583 :         List rules = new ArrayList();
584 : 
585 :         String[] ERAs = symbols.getEras();
586 :         String[] months = symbols.getMonths();
587 :         String[] shortMonths = symbols.getShortMonths();
588 :         String[] weekdays = symbols.getWeekdays();
589 :         String[] shortWeekdays = symbols.getShortWeekdays();
590 :         String[] AmPmStrings = symbols.getAmPmStrings();
591 : 
592 :         int length = mPattern.length();
593 :         int[] indexRef = new int[1];
594 : 
595 :         for (int i = 0; i < length; i++) {
596 :             indexRef[0] = i;
597 :             String token = parseToken(mPattern, indexRef);
598 :             i = indexRef[0];
599 : 
600 :             int tokenLen = token.length();
601 :             if (tokenLen == 0) {
602 :                 break;
603 :             }
604 : 
605 :             Rule rule;
606 :             char c = token.charAt(0);
607 : 
608 :             switch (c) {
609 :             case 'G': // era designator (text)
610 :                 rule = new TextField(Calendar.ERA, ERAs);
611 :                 break;
612 :             case 'y': // year (number)
613 :                 if (tokenLen >= 4) {
614 :                     rule = selectNumberRule(Calendar.YEAR, tokenLen);
615 :                 } else {
616 :                     rule = TwoDigitYearField.INSTANCE;
617 :                 }
618 :                 break;
619 :             case 'M': // month in year (text and number)
620 :                 if (tokenLen >= 4) {
621 :                     rule = new TextField(Calendar.MONTH, months);
622 :                 } else if (tokenLen == 3) {
623 :                     rule = new TextField(Calendar.MONTH, shortMonths);
624 :                 } else if (tokenLen == 2) {
625 :                     rule = TwoDigitMonthField.INSTANCE;
626 :                 } else {
627 :                     rule = UnpaddedMonthField.INSTANCE;
628 :                 }
629 :                 break;
630 :             case 'd': // day in month (number)
631 :                 rule = selectNumberRule(Calendar.DAY_OF_MONTH, tokenLen);
632 :                 break;
633 :             case 'h': // hour in am/pm (number, 1..12)
634 :                 rule = new TwelveHourField(selectNumberRule(Calendar.HOUR, tokenLen));
635 :                 break;
636 :             case 'H': // hour in day (number, 0..23)
637 :                 rule = selectNumberRule(Calendar.HOUR_OF_DAY, tokenLen);
638 :                 break;
639 :             case 'm': // minute in hour (number)
640 :                 rule = selectNumberRule(Calendar.MINUTE, tokenLen);
641 :                 break;
642 :             case 's': // second in minute (number)
643 :                 rule = selectNumberRule(Calendar.SECOND, tokenLen);
644 :                 break;
645 :             case 'S': // millisecond (number)
646 :                 rule = selectNumberRule(Calendar.MILLISECOND, tokenLen);
647 :                 break;
648 :             case 'E': // day in week (text)
649 :                 rule = new TextField(Calendar.DAY_OF_WEEK, tokenLen < 4 ? shortWeekdays : weekdays);
650 :                 break;
651 :             case 'D': // day in year (number)
652 :                 rule = selectNumberRule(Calendar.DAY_OF_YEAR, tokenLen);
653 :                 break;
654 :             case 'F': // day of week in month (number)
655 :                 rule = selectNumberRule(Calendar.DAY_OF_WEEK_IN_MONTH, tokenLen);
656 :                 break;
657 :             case 'w': // week in year (number)
658 :                 rule = selectNumberRule(Calendar.WEEK_OF_YEAR, tokenLen);
659 :                 break;
660 :             case 'W': // week in month (number)
661 :                 rule = selectNumberRule(Calendar.WEEK_OF_MONTH, tokenLen);
662 :                 break;
663 :             case 'a': // am/pm marker (text)
664 :                 rule = new TextField(Calendar.AM_PM, AmPmStrings);
665 :                 break;
666 :             case 'k': // hour in day (1..24)
667 :                 rule = new TwentyFourHourField(selectNumberRule(Calendar.HOUR_OF_DAY, tokenLen));
668 :                 break;
669 :             case 'K': // hour in am/pm (0..11)
670 :                 rule = selectNumberRule(Calendar.HOUR, tokenLen);
671 :                 break;
672 :             case 'z': // time zone (text)
673 :                 if (tokenLen >= 4) {
674 :                     rule = new TimeZoneNameRule(mTimeZone, mTimeZoneForced, mLocale, TimeZone.LONG);
675 :                 } else {
676 :                     rule = new TimeZoneNameRule(mTimeZone, mTimeZoneForced, mLocale, TimeZone.SHORT);
677 :                 }
678 :                 break;
679 :             case 'Z': // time zone (value)
680 :                 if (tokenLen == 1) {
681 :                     rule = TimeZoneNumberRule.INSTANCE_NO_COLON;
682 :                 } else {
683 :                     rule = TimeZoneNumberRule.INSTANCE_COLON;
684 :                 }
685 :                 break;
686 :             case '\'': // literal text
687 :                 String sub = token.substring(1);
688 :                 if (sub.length() == 1) {
689 :                     rule = new CharacterLiteral(sub.charAt(0));
690 :                 } else {
691 :                     rule = new StringLiteral(sub);
692 :                 }
693 :                 break;
694 :             default:
695 :                 throw new IllegalArgumentException("Illegal pattern component: " + token);
696 :             }
697 : 
698 :             rules.add(rule);
699 :         }
700 : 
701 :         return rules;
702 :     }"

